        const up = (arr, i) => { const gg = g[idx] / o.batch * cl; m[idx] = 0.9 * m[idx] + 0.1 * gg; s[idx] = 0.999 * s[idx] + 0.001 * gg * gg; arr[i] -= lr * (m[idx] / (1 - Math.pow(0.9, it))) / (Math.sqrt(s[idx] / (1 - Math.pow(0.999, it))) + 1e-8); idx++; };
        P.W.forEach(row => row.forEach((_, j) => up(row, j))); P.B.forEach(row => row.forEach((_, j) => up(row, j))); P.c.forEach((_, i) => up(P.c, i)); P.K.forEach((_, i) => up(P.K, i));
