    function rollout(P, d, t0, M, K) { const H = P.c.length; let h = new Float64Array(H), cur = d.y[t0]; const out = []; for (let k = 0; k < M + K - 1; k++) { const yi = k < M ? d.y[t0 + k] : cur, ai = d.a[t0 + k], h2 = new Float64Array(H); for (let i = 0; i < H; i++) { let z = P.c[i] + P.B[i][0] * yi + P.B[i][1] * ai; for (let j = 0; j < H; j++) z += P.W[i][j] * h[j]; h2[i] = Math.tanh(z); } h = h2; let v = yi; for (let i = 0; i < H; i++) v += P.K[i] * h[i]; cur = v; if (k >= M - 1) out.push(v); } return out; }
    function errCurve(P, tests, M, K) { const e = new Float64Array(K); let den = 0; for (const d of tests) for (let w = 0; w < 6; w++) { const t0 = Math.floor(w * (d.y.length - M - K - 1) / 6), o = rollout(P, d, t0, M, K); for (let k = 0; k < K; k++) { e[k] += Math.abs(o[k] - d.x[t0 + M + k]); den += Math.abs(d.x[t0 + M + k]) / K; } } return Array.from(e).map(v => v / den); }
    let fitCache = null;
