      if (fitCache) return fitCache;
      const t0 = Date.now(), r = rng(5), train = [], test = []; for (let i = 0; i < 30; i++) train.push(makeTraj(r, 200, 0.02)); for (let i = 0; i < 6; i++) test.push(makeTraj(r, 200, 0.02));
